@RestController
@RequestMapping("/api/v1/orders")
@Validated
public class OrderController {

    private final OrderService orderService;

    public OrderController(OrderService orderService) {
        this.orderService = orderService;
    }

    @PostMapping
    public ResponseEntity<OrderResponseDto> createOrder(@Valid @RequestBody OrderCreateRequestDto request) {
        // Review check: Controller delegates immediately to Service; no business logic here.
        OrderDto order = orderService.processNewOrder(request);
        return ResponseEntity.status(HttpStatus.CREATED).body(new OrderResponseDto(order));
    }
}
